command:
$ErrorActionPreference = "Stop"
Write-Host "===== BOOKMARK FINAL PRE-MAIN RETEST ====="
git fetch origin main work/bookmarks-winui --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "5228cbbfc24f56d61a84975545f1d8572e7deece") { throw "main moved" }
$status=@(git status --short)
if($status.Count -ne 0){$status|%{Write-Host $_};throw "unexpected local changes"}
git checkout work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "checkout failed" }
git merge --ff-only origin/work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "branch ff failed" }
Write-Host "BOOKMARK_BRANCH_HEAD=$(git rev-parse HEAD)"

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
$env:FLY_MIGRATION_CONFIGURATION="Release"
python -X utf8 tests\winui\test_bookmark_gui.py
if ($LASTEXITCODE -ne 0) { throw "bookmark GUI failed" }

if (-not (Test-Path "logs\capture-bookmark-visual.py")) { throw "capture helper missing" }
$env:BOOKMARK_VISUAL_MODE="after"
python -X utf8 logs\capture-bookmark-visual.py
if ($LASTEXITCODE -ne 0) { throw "after capture failed" }

python -X utf8 -c "from PIL import Image,ImageChops,ImageStat; from pathlib import Path; import hashlib; b=Path('logs/bookmark-visual-before.png'); a=Path('logs/bookmark-visual-after.png'); ib=Image.open(b).convert('RGB'); ia=Image.open(a).convert('RGB'); d=ImageChops.difference(ib,ia); print('BEFORE_SIZE',ib.size); print('AFTER_SIZE',ia.size); print('DIFF_BBOX',d.getbbox()); print('DIFF_MEAN',tuple(round(x,3) for x in ImageStat.Stat(d).mean)); print('BEFORE_SHA256',hashlib.sha256(b.read_bytes()).hexdigest()); print('AFTER_SHA256',hashlib.sha256(a.read_bytes()).hexdigest())"
if ($LASTEXITCODE -ne 0) { throw "visual metadata failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }

$bookmarkHead=(git rev-parse HEAD).Trim()
git switch --detach origin/main
if ($LASTEXITCODE -ne 0) { throw "cannot detach for evidence branch" }
git branch -D evidence/bookmark-visual 2>$null
git switch -c evidence/bookmark-visual
if ($LASTEXITCODE -ne 0) { throw "cannot create evidence branch" }
New-Item -ItemType Directory -Force -Path evidence\bookmark-visual | Out-Null
Copy-Item logs\bookmark-visual-before.png evidence\bookmark-visual\before.png -Force
Copy-Item logs\bookmark-visual-after.png evidence\bookmark-visual\after.png -Force
git add -f evidence\bookmark-visual\before.png evidence\bookmark-visual\after.png
git -c user.name="flyExplorer Validation" -c user.email="actions@users.noreply.github.com" commit -m "evidence: temporary bookmark visual acceptance"
if ($LASTEXITCODE -ne 0) { throw "evidence commit failed" }
git push --force origin evidence/bookmark-visual
if ($LASTEXITCODE -ne 0) { throw "evidence push failed" }
git checkout work/bookmarks-winui
if ($LASTEXITCODE -ne 0) { throw "cannot restore bookmark branch" }
if ((git rev-parse HEAD).Trim() -ne $bookmarkHead) { throw "bookmark branch changed while publishing evidence" }
Write-Host "BOOKMARK_FINAL_PREMAIN_PASS"
